        Exception lastFailure = null;
        for (int attempt = 1; attempt <= maxAttempts; attempt++) {
            try {
                return operation.call();
            } catch (Exception e) {
                lastFailure = e;
            }
        }
        if (lastFailure instanceof RuntimeException) {
            throw (RuntimeException) lastFailure;
